// 当地有权者决定下一tick起的新税政；不征税、不回滚旧税期、不触碰私人钱包。
#include "politics_fiscal.hpp"
#include "politics_fiscal_time2.hpp"
#include "politics_internal.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <limits>
#include <map>
namespace hanmo::resident {
namespace {
// 税政只认已定义的三档；无政策由optional empty表达，不能落入normal默认值。
bool valid_mode(FiscalTaxMode mode){return mode==FiscalTaxMode::lenient||mode==FiscalTaxMode::normal||mode==FiscalTaxMode::surcharge;}
// 最近记录含尚未生效的改变，避免同tick两次决定用旧revision覆盖彼此。
Integer current_revision(const PoliticalFiscalState& state,const StableId& jurisdiction){Integer revision=0;for(const auto& row:state.policies.rows())if(row.second.snapshot.jurisdiction_id==jurisdiction)revision=std::max(revision,row.second.snapshot.policy_revision);return revision;}
// 签发能力、治所及两个公库必须由同一真实Grant覆盖。
const Grant* fiscal_grant(const OrganizationState& org,const OrganizationCatalog& catalog,const ActingAuthority& authority,const Jurisdiction& j,const StableId& inventory,Integer tick){const auto* office=org.offices.find(authority.office_id);if(!office)return nullptr;for(const auto& id:office->grant_ids){const auto* grant=catalog.grants.find(id);if(!grant||grant->office_id!=office->id||grant->amount_limit<0||grant->valid_from>tick||(grant->valid_until&&tick>*grant->valid_until))continue;const auto has=[](const auto& rows,const auto& value){return std::find(rows.begin(),rows.end(),value)!=rows.end();};if(has(grant->allowed_command_kinds,StableId{"political_set_tax"})&&has(grant->wallet_ids,j.public_wallet_id)&&has(grant->inventory_ids,inventory)&&std::any_of(grant->scopes.begin(),grant->scopes.end(),[&](const auto& s){return s.kind==ScopeRef::Kind::site&&s.id==j.seat_place_id;}))return grant;}return nullptr;}
// 来源头与不可变政策记录必须一致，读口不能接受任意已有fact作为征税理由。
Status source_valid(const CommonStore& common,const FiscalPolicyRecord& record){if(record.issued_at)return common_failure("PoliticalFiscalLegacyMomentForbidden",record.id);const auto* fact=common.state().facts.find(record.id);const auto& p=record.snapshot;const auto sequence=organization_instance_sequence(record.id,"politics_fiscal");if(!sequence||*sequence>=common.state().next_instance_id||record.id.empty()||p.source_fact_id!=record.id||!fact||fact->domain!="politics"||fact->kind!="political_fiscal_policy_changed"||p.policy_revision<1||p.issued_tick<0||p.issued_tick>common.tick()||p.issued_tick==INT64_MAX||p.effective_from_tick!=p.issued_tick+1||!valid_mode(p.mode))return common_failure("InvalidFiscalPolicySource",record.id);return common_success();}
}
FiscalPolicyAccess::FiscalPolicyAccess(const CommonStore& c,const CommonCatalog& cc,const PoliticsState& politics,const PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const FiscalPolicyOccupationRead* occupation):common_(c),common_catalog_(cc),politics_(politics),state_(state),catalog_(catalog),occupation_(occupation){}
FiscalPolicyAccess::FiscalPolicyAccess(const CommonStore& c,const CommonCatalog& cc,const PoliticsState& politics,const PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const DynamicStepInput& step,const FiscalPolicyOccupationRead* occupation):FiscalPolicyAccess(c,cc,politics,state,catalog,occupation){phase_boundary_=std::make_pair(step.from_tick,step.to_tick);}
FiscalPolicyAccess::FiscalPolicyAccess(const PoliticalFiscalTime2Context& x):common_(x.common),common_catalog_(x.common_catalog),politics_(x.politics),state_(x.state),catalog_(x.catalog),occupation_(x.occupation),exact_(&x){}
Outcome<std::optional<FiscalPolicySnapshot>> FiscalPolicyAccess::fiscal_policy_for_due_tick(const StableId& site,Integer due)const{return select_policy(site,due,nullptr);}
Outcome<std::optional<FiscalPolicySnapshot>> FiscalPolicyAccess::fiscal_policy_for_assessment_source(const StableId& site,Integer due,const StableId& source)const{return select_policy(site,due,&source);}
Outcome<std::optional<FiscalPolicySnapshot>> FiscalPolicyAccess::select_policy(const StableId& site,Integer due,const StableId* historical)const{
    const auto fail=[](const StableId& code,const StableId& id){return Outcome<std::optional<FiscalPolicySnapshot>>{false,{},common_failure(code,id).error};};
    Integer evaluation_tick=common_.tick();
    if(exact_){if(catalog_.version!=2||state_.version!=2)return fail("PoliticalFiscalTime2VersionRequired",site);auto now=read_organization_authority_now(common_,&exact_->clock);if(!now.ok)return {false,{},now.error};evaluation_tick=now.value.half_day_tick;}
    else if(catalog_.version!=1||state_.version!=1)return fail("PoliticalFiscalActualClockRequired",site);
    if(phase_boundary_){const auto from=phase_boundary_->first,to=phase_boundary_->second;if(from<0||from!=common_.tick()||from==INT64_MAX||to!=from+1)return fail("FiscalPhaseBoundaryMismatch",site);evaluation_tick=to;}
    if(due<0||due>evaluation_tick)return fail("FutureOrInvalidFiscalAssessment",site);
    if(!common_catalog_.places.find(site))return fail("UnknownFiscalSite",site);
    if(!catalog_.enabled)return historical?fail("FiscalAssessmentPolicySourceMismatch",*historical):Outcome<std::optional<FiscalPolicySnapshot>>{true,std::nullopt,{}};
    const Jurisdiction* jurisdiction=nullptr;
    for(const auto& row:politics_.jurisdictions.rows())if(row.second.seat_place_id==site){if(jurisdiction)return fail("AmbiguousFiscalJurisdiction",site);jurisdiction=&row.second;}
    if(!jurisdiction)return historical?fail("FiscalAssessmentPolicySourceMismatch",*historical):Outcome<std::optional<FiscalPolicySnapshot>>{true,std::nullopt,{}};
    if(!occupation_&&jurisdiction->controlling_organization_id!=jurisdiction->political_organization_id)return fail("PoliticalFiscalOccupationUnsupported",jurisdiction->id);
    const FiscalPolicyRecord* selected=nullptr;
    for(const auto& row:state_.policies.rows()){
        const auto& p=row.second.snapshot;if(p.jurisdiction_id!=jurisdiction->id||p.effective_from_tick>due)continue;
        auto valid=exact_?validate_political_fiscal_record2(*exact_,row.second):source_valid(common_,row.second);if(!valid.ok)return {false,{},valid.error};
        if(p.site_id!=site||p.organization_id!=jurisdiction->political_organization_id||p.public_wallet_id!=jurisdiction->public_wallet_id||std::find(jurisdiction->public_inventory_ids.begin(),jurisdiction->public_inventory_ids.end(),p.public_inventory_id)==jurisdiction->public_inventory_ids.end())return fail("FiscalPolicyJurisdictionMismatch",row.first);
        if(!selected||p.policy_revision>selected->snapshot.policy_revision)selected=&row.second;
    }
    if(historical&&(!selected||selected->id!=*historical))return fail("FiscalAssessmentPolicySourceMismatch",*historical);
    if(!selected)return {true,std::nullopt,{}};
    const auto& p=selected->snapshot;
    if(occupation_){
        auto source=occupation_->fiscal_policy_occupation(p);if(!source.ok)return {false,{},source.error};
        if(source.value){bool lost=false;if(exact_){auto verified=validate_political_fiscal_occupation_boundary2(*exact_,*source.value);if(!verified.ok)return {false,{},verified.error};auto compared=compare_world_moments(WorldMoment{due,{}},*source.value->actual_occupation_at);if(!compared.ok)return {false,{},compared.error};lost=historical?compared.value>0:compared.value>=0;}else lost=historical?due>source.value->occupation_tick:due>=source.value->occupation_tick;if(lost)return historical?fail("FiscalAssessmentAfterControlLoss",*historical):Outcome<std::optional<FiscalPolicySnapshot>>{true,std::nullopt,{}};return {true,p,{}};}
    }
    const auto* wallet=common_.wallet(p.public_wallet_id);const auto* stock=common_.inventory(p.public_inventory_id);
    if(!wallet||!stock||wallet->owner.kind!=Owner::Kind::organization||wallet->owner.id!=p.organization_id||stock->owner.kind!=Owner::Kind::organization||stock->owner.id!=p.organization_id)return fail("FiscalPublicAssetMismatch",selected->id);
    return {true,p,{}};
}
Status preview_political_set_tax(const CommonStore& c,const PoliticsState& politics,const PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const OrganizationState& org,const OrganizationCatalog& oc,const ActivityRead& activity,const StableId& actor,const PoliticalSetTaxCommand& command){if(catalog.version!=1||state.version!=1)return common_failure("PoliticalFiscalLegacyVersionRequired");if(!catalog.enabled)return common_failure("PoliticalFiscalNotEnabled",{},ErrorKind::unsupported_capability);if(actor!=command.authority.actor_id)return common_failure("PoliticalCommandActorMismatch");if(!valid_mode(command.mode))return common_failure("InvalidFiscalTaxMode");const auto* j=politics.jurisdictions.find(command.jurisdiction_id);if(!j)return common_failure("UnknownPoliticalJurisdiction",command.jurisdiction_id);if(j->revision!=command.expected_jurisdiction_revision)return common_failure("StalePoliticalJurisdiction",j->id);if(j->political_organization_id!=command.authority.organization_id||j->controlling_organization_id!=command.authority.organization_id)return common_failure("PoliticalControlDenied",j->id);if(current_revision(state,j->id)!=command.expected_policy_revision)return common_failure("StaleFiscalPolicy",j->id);if(command.expected_policy_revision==INT64_MAX||c.tick()==INT64_MAX)return common_failure("FiscalPolicyCounterOverflow",j->id);auto available=politics_detail::available(c,activity,actor);if(!available.ok)return available;auto age=growth_independent_office_age(c,actor);if(!age.ok)return age;const auto here=politics_detail::place(c,actor);if(!here||here->place_id!=j->seat_place_id)return common_failure("FiscalPolicyRequiresLocalAuthority",j->seat_place_id);if(std::find(j->public_inventory_ids.begin(),j->public_inventory_ids.end(),command.public_inventory_id)==j->public_inventory_ids.end())return common_failure("FiscalPublicInventoryMismatch",command.public_inventory_id);const auto* wallet=c.wallet(j->public_wallet_id);const auto* stock=c.inventory(command.public_inventory_id);if(!wallet||wallet->owner.kind!=Owner::Kind::organization||wallet->owner.id!=j->political_organization_id||!stock||stock->owner.kind!=Owner::Kind::organization||stock->owner.id!=j->political_organization_id)return common_failure("FiscalPublicAssetMismatch",j->id);auto authorized=check_authority(c,org,oc,command.authority,"political_set_tax",{ScopeRef::Kind::site,j->seat_place_id},0);if(!authorized.ok)return {false,{},authorized.error};if(!fiscal_grant(org,oc,command.authority,*j,command.public_inventory_id,c.tick()))return common_failure("FiscalGrantIncomplete",j->id);return common_success();}
Outcome<PoliticalFiscalEffects> apply_political_set_tax_in_transaction(CommonStore& c,const PoliticsState& politics,PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const OrganizationState& org,const OrganizationCatalog& oc,const ActivityRead& activity,const StableId& actor,const PoliticalSetTaxCommand& command){auto checked=preview_political_set_tax(c,politics,state,catalog,org,oc,activity,actor,command);if(!checked.ok)return {false,{},checked.error};auto next=state;const auto* j=politics.jurisdictions.find(command.jurisdiction_id);const auto* grant=fiscal_grant(org,oc,command.authority,*j,command.public_inventory_id,c.tick());auto id=c.next_id("politics_fiscal");if(!id.ok)return {false,{},id.error};FiscalPolicyRecord record;record.id=id.value;record.issuer_actor_id=actor;record.issuer_office_id=command.authority.office_id;record.authority_epoch=command.authority.authority_epoch;record.grant_id=grant->id;auto& p=record.snapshot;p.jurisdiction_id=j->id;p.site_id=j->seat_place_id;p.organization_id=j->political_organization_id;p.public_wallet_id=j->public_wallet_id;p.public_inventory_id=command.public_inventory_id;p.source_fact_id=id.value;p.policy_revision=command.expected_policy_revision+1;p.issued_tick=c.tick();p.effective_from_tick=c.tick()+1;p.mode=command.mode;auto fact=c.append_fact({id.value,"political_fiscal_policy_changed","politics"});if(!fact.ok)return {false,{},fact.error};next.policies.insert(id.value,std::move(record));state=std::move(next);return {true,{id.value,command.expected_policy_revision+1,c.tick()+1},{}};}
// 独立领域调用持自己的savepoint；中央已持完整候选时使用明确内层入口。
Outcome<PoliticalFiscalEffects> apply_political_set_tax(CommonStore& c,const PoliticsState& politics,PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const OrganizationState& org,const OrganizationCatalog& oc,const ActivityRead& activity,const StableId& actor,const PoliticalSetTaxCommand& command){local_economy_detail::PhaseSavepoint guard(c);if(!guard.token().ok)return {false,{},guard.token().error};auto next=state;auto result=apply_political_set_tax_in_transaction(c,politics,next,catalog,org,oc,activity,actor,command);if(!result.ok)return result;auto committed=guard.commit();if(!committed.ok)return {false,{},committed.error};state=std::move(next);return result;}
// 验证历史签发者存在和原Grant边界；离任或死亡不将已经成立的税期政策悄悄改写。
Status validate_political_fiscal(const CommonStore& c,const CommonCatalog& cc,const PoliticsState& politics,const PoliticalFiscalState& state,const PoliticalFiscalCatalog& catalog,const OrganizationState& org,const OrganizationCatalog& oc,const FiscalPolicyOccupationRead* occupation){if(catalog.version!=1||state.version!=1)return common_failure("PoliticalFiscalLegacyVersionRequired");for(const auto& row:state.policies.rows())if(row.second.issued_at)return common_failure("PoliticalFiscalLegacyMomentForbidden",row.first);for(const auto& fact:c.state().facts.rows())if(fact.second.domain=="politics"&&fact.second.kind=="political_fiscal_policy_changed"&&!state.policies.find(fact.first))return common_failure("OrphanFiscalPolicySource",fact.first);if(!catalog.enabled)return state.policies.empty()?common_success():common_failure("DisabledFiscalPolicyHasState");std::map<StableId,Integer> revisions,ticks;for(const auto& row:state.policies.rows()){const auto& r=row.second;const auto& p=r.snapshot;auto source=source_valid(c,r);if(!source.ok)return source;if(occupation){auto boundary=occupation->fiscal_policy_occupation(p);if(!boundary.ok)return {false,{},boundary.error};}const auto* j=politics.jurisdictions.find(p.jurisdiction_id);const auto* office=org.offices.find(r.issuer_office_id);const auto* grant=oc.grants.find(r.grant_id);if(row.first!=r.id||!j||!cc.places.find(p.site_id)||p.site_id!=j->seat_place_id||p.organization_id!=j->political_organization_id||p.public_wallet_id!=j->public_wallet_id||std::find(j->public_inventory_ids.begin(),j->public_inventory_ids.end(),p.public_inventory_id)==j->public_inventory_ids.end()||!c.actor(r.issuer_actor_id)||!office||office->organization_id!=p.organization_id||r.authority_epoch<0||r.authority_epoch>office->epoch||!grant||grant->office_id!=office->id||grant->valid_from>p.issued_tick||(grant->valid_until&&p.issued_tick>*grant->valid_until))return common_failure("InvalidFiscalPolicyRecord",row.first);if(p.policy_revision!=revisions[p.jurisdiction_id]+1||(revisions[p.jurisdiction_id]&&p.issued_tick<ticks[p.jurisdiction_id]))return common_failure("FiscalPolicyHistoryMismatch",row.first);auto signer=validate_historical_office_signer(c,org,oc,{p.organization_id,r.issuer_office_id,r.authority_epoch,r.issuer_actor_id},p.issued_tick,*organization_instance_sequence(r.id,"politics_fiscal"));if(!signer.ok)return signer;const auto* initial=oc.offices.find(r.issuer_office_id);if(!initial||std::find(initial->grant_ids.begin(),initial->grant_ids.end(),r.grant_id)==initial->grant_ids.end())return common_failure("FiscalPolicyGrantMismatch",row.first);revisions[p.jurisdiction_id]=p.policy_revision;ticks[p.jurisdiction_id]=p.issued_tick;const auto has=[](const auto& values,const StableId& id){return std::find(values.begin(),values.end(),id)!=values.end();};if(!has(grant->allowed_command_kinds,"political_set_tax")||!has(grant->wallet_ids,p.public_wallet_id)||!has(grant->inventory_ids,p.public_inventory_id)||std::none_of(grant->scopes.begin(),grant->scopes.end(),[&](const auto& s){return s.kind==ScopeRef::Kind::site&&s.id==p.site_id;}))return common_failure("FiscalPolicyGrantMismatch",row.first);}return common_success();}
// 政策决定由实际签发者和组织持有消息，经济收入另有经济域收据，绝不在这里宣称已收税。
std::optional<DynamicFactView> political_fiscal_dynamic_fact(const PoliticalFiscalState& state,const StableId& id){const auto* r=state.policies.find(id);if(!r)return {};DynamicFactView out;out.id=id;out.kind="political_fiscal_policy_changed";out.rule_version=state.version==2?"politics_fiscal_v2":"politics_fiscal_v1";out.tick=r->snapshot.issued_tick;out.subject_id=r->snapshot.jurisdiction_id;out.outcome=r->snapshot.mode==FiscalTaxMode::lenient?"lenient":r->snapshot.mode==FiscalTaxMode::normal?"normal":"surcharge";out.participants={{{SubjectKind::actor,r->issuer_actor_id},"issuer"},{{SubjectKind::organization,r->snapshot.organization_id},"principal"}};return out;}
} // 只有后续真实政策替换影响新到期责任，历史记录和source_fact保持不可变。
